-- Fixture-only transactions. Every probe rolls back, even if a policy regresses.
begin;
select no_plan();
create function pg_temp.fixture_id(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.fixture_id(703),'isolation-staff@example.test'),(pg_temp.fixture_id(704),'isolation-a@example.test'),(pg_temp.fixture_id(705),'isolation-b@example.test');
update public.profiles set role='staff' where id=pg_temp.fixture_id(703);
insert into public.brands(id,name) values(pg_temp.fixture_id(701),'Isolation A'),(pg_temp.fixture_id(702),'Isolation B');
insert into public.brand_users(brand_id,user_id) values(pg_temp.fixture_id(701),pg_temp.fixture_id(704)),(pg_temp.fixture_id(702),pg_temp.fixture_id(705));
insert into public.customers(id,legal_name) values(pg_temp.fixture_id(706),'Isolation customer');
insert into public.customer_contacts(customer_id,name) values(pg_temp.fixture_id(706),'Private customer contact');
create temporary table isolation_scopes(scope text,brand_id uuid,season_id uuid,product_id uuid,variant_id uuid,order_id uuid,budget_id uuid,event_id uuid,document_id uuid,user_id uuid);
insert into isolation_scopes values('A',pg_temp.fixture_id(701),pg_temp.fixture_id(710),pg_temp.fixture_id(720),pg_temp.fixture_id(730),null,pg_temp.fixture_id(740),pg_temp.fixture_id(750),pg_temp.fixture_id(760),pg_temp.fixture_id(704)),('B',pg_temp.fixture_id(702),pg_temp.fixture_id(711),pg_temp.fixture_id(721),pg_temp.fixture_id(731),null,pg_temp.fixture_id(741),pg_temp.fixture_id(751),pg_temp.fixture_id(761),pg_temp.fixture_id(705));
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000703';
do $$declare s record;v_order uuid;begin
for s in select * from isolation_scopes loop
insert into public.brand_private(id,notes) values(s.brand_id,'Private brand');
insert into public.brand_contacts(brand_id,name) values(s.brand_id,'Private contact');
insert into public.seasons(id,brand_id,code,name) values(s.season_id,s.brand_id,'ISOLATION','Isolation season');
insert into public.products(id,brand_id,season_id,sku_base,name,wholesale_price_cents) values(s.product_id,s.brand_id,s.season_id,'ISOLATION-'||s.scope,'Isolation product',1000);
insert into public.product_variants(id,brand_id,product_id,size,color,sku) values(s.variant_id,s.brand_id,s.product_id,'M','Nero','ISOLATION-'||s.scope||'-M');
v_order:=public.save_order(null,jsonb_build_object('brand_id',s.brand_id,'customer_id',pg_temp.fixture_id(706),'season_id',s.season_id,'order_date','2033-01-01','discount_pct',0,'internal_notes','Isolation secret'),jsonb_build_array(jsonb_build_object('variant_id',s.variant_id,'quantity',1,'unit_price_cents',1000,'discount_pct',0)));
perform public.change_order_status(v_order,'confirmed','');
update isolation_scopes set order_id=v_order where scope=s.scope;
insert into public.budgets(id,brand_id,amount_cents,period_start,period_end) values(s.budget_id,s.brand_id,5000,'2033-01-01','2033-12-31');
insert into public.budget_private(id,brand_id,notes) values(s.budget_id,s.brand_id,'Private budget');
insert into public.invoices(number,brand_id,customer_id,order_id,status,issue_date,due_date,net_cents,vat_cents,gross_cents) values('ISOLATION-'||s.scope,s.brand_id,pg_temp.fixture_id(706),v_order,'issued','2033-01-01','2033-02-01',1000,220,1220);
insert into public.invoice_counters(brand_id,year,last_number) values(s.brand_id,2033,1);
insert into public.mock_invoice_records(id,brand_id,idempotency_key,external_id,fingerprint,status) select id,s.brand_id,idempotency_key,'mock_'||id::text,repeat('a',64),'issued' from public.invoices where number='ISOLATION-'||s.scope;
insert into public.invoice_webhook_events(event_id,provider,invoice_id,brand_id,external_status) select 'isolation-'||s.scope,'mock',id,s.brand_id,'issued' from public.invoices where number='ISOLATION-'||s.scope;
insert into public.payments(invoice_id,brand_id,amount_cents,paid_at,method) select id,s.brand_id,100,'2033-01-02T10:00Z','bank_transfer' from public.invoices where number='ISOLATION-'||s.scope;
insert into public.events(id,brand_id,title,starts_at,ends_at,visible_to_brand,assigned_to) values(s.event_id,s.brand_id,'Shared isolation','2033-01-01T09:00Z','2033-01-01T10:00Z',true,pg_temp.fixture_id(703));
insert into public.event_reminders(event_id,recipient_id,starts_at) values(s.event_id,pg_temp.fixture_id(703),'2033-01-01T09:00Z');
insert into public.documents(id,name,brand_id,storage_path,original_filename,mime_type,size_bytes,uploaded_by,shared_with_brand) values(s.document_id,'Shared isolation',s.brand_id,s.brand_id::text||'/'||s.document_id::text||'.pdf','isolation.pdf','application/pdf',10,pg_temp.fixture_id(703),true);
insert into storage.objects(bucket_id,name,metadata) values('documents',s.brand_id::text||'/'||s.document_id::text||'.pdf','{"size":10,"mimetype":"application/pdf"}');
update public.documents set ready=true where id=s.document_id;
insert into public.ical_tokens(user_id,token_hash) values(s.user_id,repeat(case when s.scope='A' then 'a' else 'b' end,64));
end loop;end;$$;
insert into storage.buckets(id,name,public) values('isolation-other','isolation-other',false);

create temporary table fic_fixture(scope text primary key,id uuid,lease uuid,record jsonb,queue_id uuid,queue_lease uuid);
grant all on isolation_scopes,fic_fixture to authenticated,service_role;
select public.change_order_status(order_id,'in_production','') from isolation_scopes;
select public.change_order_status(order_id,'shipped','') from isolation_scopes;
select public.change_order_status(order_id,'delivered','') from isolation_scopes;
update public.profiles set role='accounting' where id=pg_temp.fixture_id(703);
set local role authenticated;
insert into fic_fixture(scope,id) select scope,public.reserve_invoice_from_order(order_id,'2033-01-02','2033-02-02','fic') from isolation_scopes;
select throws_ok($$select public.fic_prepare_invoice(id,12345,repeat('a',64)) from fic_fixture where scope='A'$$,'55P03',null,'journal requires an active emission claim');
update fic_fixture set lease=public.claim_invoice_issue(id);
select throws_ok($$select public.fic_prepare_invoice(id,0,repeat('a',64)) from fic_fixture where scope='A'$$,'22023',null,'company ID is validated');
select throws_ok($$select public.fic_prepare_invoice(id,12345,'invalid') from fic_fixture where scope='A'$$,'22023',null,'fingerprint is validated');
update fic_fixture set record=public.fic_prepare_invoice(id,12345,repeat('a',64)) where scope='A';
select is((select record->>'state' from fic_fixture where scope='A'),'prepared','first request is prepared durably');
select is((select public.fic_prepare_invoice(id,12345,repeat('a',64))->>'state' from fic_fixture where scope='A'),'prepared','same request is idempotent');
select throws_ok($$select public.fic_prepare_invoice(id,99999,repeat('a',64)) from fic_fixture where scope='A'$$,'23505',null,'same invoice cannot silently change issuing company');
select throws_ok($$select public.fic_prepare_invoice(id,12345,repeat('b',64)) from fic_fixture where scope='A'$$,'23505',null,'changed immutable request conflicts');
select is((select public.fic_mark_attempt(id) from fic_fixture where scope='A'),true,'first creation attempt is claimed atomically');
select is((select public.fic_mark_attempt(id) from fic_fixture where scope='A'),false,'second creation attempt never obtains permission to POST');
select is((select fic_request_state from public.invoices where id=(select id from fic_fixture where scope='A')),'uncertain','network outcome remains uncertain across isolates');
select public.fic_definite_failure(id) from fic_fixture where scope='A';
select is((select fic_request_state from public.invoices where id=(select id from fic_fixture where scope='A')),'prepared','definite rejection permits retry');
select public.fic_mark_attempt(id) from fic_fixture where scope='A';
select public.fic_link_invoice(id,500,'17/MDC') from fic_fixture where scope='A';
select is((select fic_document_number from public.invoices where id=(select id from fic_fixture where scope='A')),'17/MDC','real number is separate from immutable local number');
select lives_ok($$select public.fic_link_invoice(id,500,'17/MDC') from fic_fixture where scope='A'$$,'external reference link is idempotent');
select throws_ok($$select public.fic_link_invoice(id,501,'18/MDC') from fic_fixture where scope='A'$$,'23505',null,'external reference cannot be replaced');
select throws_ok($$select public.finish_invoice_issue(id,lease,'fic_99999_500','issued') from fic_fixture where scope='A'$$,'23514',null,'finalization checks recorded company and document');
select is((select public.finish_invoice_issue(id,lease,'fic_12345_500','issued') from fic_fixture where scope='A'),true,'known external reference finalizes invoice and order');
select is((select status::text from public.orders where id=(select order_id from isolation_scopes where scope='A')),'invoiced','order and issued invoice transition together');
select throws_ok($$select public.reconcile_invoice_status(id,'fic_12345_501','paid') from fic_fixture where scope='A'$$,'P0002',null,'polling cannot replace a reference');
select throws_ok($$select public.enqueue_fic_webhook('event',12345,array[500]::bigint[],repeat('a',64))$$,'42501',null,'interactive users cannot enqueue unverified notifications');
select throws_ok($$select public.claim_fic_webhooks()$$,'42501',null,'interactive users cannot claim notification jobs');
update fic_fixture set lease=public.claim_invoice_cancellation(id) where scope='A';
select is((select public.release_invoice_cancellation(id,gen_random_uuid()) from fic_fixture where scope='A'),false,'wrong cancellation lease cannot release a claim');
select is((select public.release_invoice_cancellation(id,lease) from fic_fixture where scope='A'),true,'definite cancellation refusal releases payment lock');
select lives_ok($$select public.register_invoice_payment(id,gen_random_uuid(),100,'2033-01-03T12:00Z','cash','') from fic_fixture where scope='A'$$,'payments remain available after refused cancellation');
-- Second invoice also tests proof before linking/finalization.
select public.fic_prepare_invoice(id,12345,repeat('b',64)) from fic_fixture where scope='B';
select throws_ok($$select public.finish_invoice_issue(id,lease,'fic_12345_501','issued') from fic_fixture where scope='B'$$,'23514',null,'unlinked external IDs cannot finalize');
select public.fic_mark_attempt(id) from fic_fixture where scope='B';
select public.fic_link_invoice(id,501,'18/MDC') from fic_fixture where scope='B';
select public.finish_invoice_issue(id,lease,'fic_12345_501','issued') from fic_fixture where scope='B';
reset role;
update public.profiles set role='staff' where id=pg_temp.fixture_id(703);
set local role authenticated;
select throws_ok($$select public.fic_prepare_invoice(id,12345,repeat('a',64)) from fic_fixture where scope='A'$$,'42501',null,'staff cannot use the creation journal');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000704';
select is((select count(*) from public.invoices where fic_company_id is not null),0::bigint,'brand cannot read issuer mappings, references or journal');
select throws_ok($$select public.fic_mark_attempt(id) from fic_fixture where scope='A'$$,'42501',null,'brand cannot initiate requests');
reset role;set local role service_role;set local request.jwt.claim.role='service_role';set local request.jwt.claim.sub='';
select is(public.enqueue_fic_webhook('fic-event',12345,array[500,501,99999]::bigint[],repeat('c',64)),2,'only locally linked documents enter the queue');
select is(public.enqueue_fic_webhook('fic-event',12345,array[500,501]::bigint[],repeat('c',64)),2,'callback replay is idempotent');
select is(public.enqueue_fic_webhook('unknown',99999,array[500]::bigint[],repeat('c',64)),0,'foreign company cannot enqueue an event');
select throws_ok($$select public.enqueue_fic_webhook('fic-event',12345,array[500]::bigint[],repeat('d',64))$$,'23505',null,'same event with altered IDs/type conflicts');
create temporary table queue_claim as select * from jsonb_to_recordset(public.claim_fic_webhooks()) as q(id uuid,lease uuid,external_id text);
select is((select count(*) from queue_claim),2::bigint,'queue claims a bounded batch');
select is(jsonb_array_length(public.claim_fic_webhooks()),0,'parallel consumer cannot claim an active lease');
select is((select public.finish_fic_webhook(id,gen_random_uuid(),'sent') from queue_claim limit 1),false,'wrong webhook lease cannot complete');
select public.fail_fic_webhook(id,lease) from queue_claim where external_id='fic_12345_501';
select is((select reconcile_error from public.invoice_webhook_events where id=(select id from queue_claim where external_id='fic_12345_501')),true,'failed fetch remains recorded for scheduled retry');
select is((select public.finish_fic_webhook(id,lease,'sent') from queue_claim where external_id='fic_12345_500'),true,'authenticated upstream state reconciles atomically');
select is((select external_status from public.invoices where external_id='fic_12345_500'),'sent','provider status updated');
select is((select reconcile_pending from public.invoice_webhook_events where id=(select id from queue_claim where external_id='fic_12345_500')),false,'completed queue entry no longer claims');
create temporary table retried as select * from jsonb_to_recordset(public.claim_fic_webhooks()) as q(id uuid,lease uuid,external_id text);
select is((select count(*) from retried),1::bigint,'failed callback is claimable again');
select is((select public.finish_fic_webhook(id,lease,'paid') from retried),true,'retried callback completes with current upstream state');
select is((select count(*) from public.payments where invoice_id=(select id from fic_fixture where scope='B')),0::bigint,'provider paid never fabricates ledger movements');
select is((select status::text from public.invoices where id=(select id from fic_fixture where scope='B')),'issued','local balance keeps business invoice unpaid');
select is(jsonb_array_length(public.claim_fic_webhooks()),0,'all finished events leave an empty queue');
reset role;
select ok(exists(select 1 from public.audit_log where table_name='invoice_webhook_events' and record_id in(select id from retried) and action='update'),'queue reconciliation audit is transactional');
select * from finish();rollback;
